               <div class="dick soft" id="dick">
                   <div class="head">
                       <div class="row"><div class="p head-d"></div><div class="p head-c"></div><div class="p head-c"></div><div class="p head-d"></div></div>
                       <div class="row"><div class="p head-c"></div><div class="p head-l"></div><div class="p head-c"></div><div class="p head-c"></div><div class="p head-c"></div></div>
                       <div class="row"><div class="p head-d"></div><div class="p head-c"></div><div class="p head-l"></div><div class="p head-c"></div><div class="p head-d"></div></div>
                       <div class="row"><div class="p skin-d"></div><div class="p head-d"></div><div class="p head-d"></div><div class="p head-d"></div><div class="p skin-d"></div></div>
                   </div>
                   <div class="shaft-body">
                       <div class="row"><div class="p skin-d"></div><div class="p skin"></div><div class="p skin-l"></div><div class="p skin"></div><div class="p skin-d"></div></div>
                       <div class="row"><div class="p skin-d"></div><div class="p skin-l"></div><div class="p skin"></div><div class="p skin"></div><div class="p skin-d"></div></div>
                       <div class="row"><div class="p skin-d"></div><div class="p skin"></div><div class="p vein"></div><div class="p skin-l"></div><div class="p skin-d"></div></div>
                       <div class="row"><div class="p skin-d"></div><div class="p skin"></div><div class="p skin"></div><div class="p skin"></div><div class="p skin-d"></div></div>
                       <div class="row"><div class="p skin-d"></div><div class="p skin-l"></div><div class="p skin"></div><div class="p vein"></div><div class="p skin-d"></div></div>
