   <script>
       const charStats = { lust: 36, semen: 79, threshold: 0 };
       let isCumming = false;

       function updateUI() {
           document.getElementById('lustBar').style.width = charStats.lust + '%';
           document.getElementById('lustVal').textContent = charStats.lust;
           document.getElementById('semenBar').style.width = charStats.semen + '%';
           document.getElementById('semenVal').textContent = charStats.semen;
           document.getElementById('threshBar').style.width = charStats.threshold + '%';
           document.getElementById('threshVal').textContent = charStats.threshold;

           document.getElementById('dreamWarning').classList.toggle('active', charStats.semen > 80);

           const dick = document.getElementById('dick');
           dick.classList.remove('soft', 'rising', 'hard');
           if (charStats.lust < 30) dick.classList.add('soft');
           else if (charStats.lust < 70) dick.classList.add('rising');
           else dick.classList.add('hard');

           if (charStats.threshold >= 100 && !isCumming && charStats.semen > 0) triggerCum();
       }

       function triggerCum() {
           if (charStats.semen <= 0) return;
           isCumming = true;

           const container = document.getElementById('cumContainer');
           container.classList.remove('cumming');
           void container.offsetWidth;
           container.classList.add('cumming');

           setTimeout(() => {
               charStats.threshold = 0;
               charStats.semen = Math.max(0, charStats.semen - 25);
               charStats.lust = Math.max(0, charStats.lust - 30);
               container.classList.remove('cumming');
               isCumming = false;
               updateUI();
           }, 1000);
       }

       window.onCharReply = function() { charStats.semen = Math.min(100, charStats.semen + 1); updateUI(); return charStats.semen > 80; };
       window.onFlirt = function(i = 5) { charStats.lust = Math.min(100, charStats.lust + i); updateUI(); };
       window.onSexTurn = function(i = 8) { charStats.threshold = Math.min(100, charStats.threshold + i); charStats.lust = Math.min(100, charStats.lust + 3); updateUI(); };
       window.resetStats = function() { charStats.lust = 20; charStats.semen = 50; charStats.threshold = 0; updateUI(); };
       window.getCharStats = function() { return { ...charStats }; };

       updateUI();
   </script>
</body>
</html>

那根**微凉的指尖**划过他掌心粗糙的纹理时，秦海一浑身的肌肉瞬间绷紧成了一块石头。

她写得很慢，力气微弱得像是一只濒死的蝴蝶在振动翅膀。但那断断续续的笔画——“你”、“再”、“要”、“1”、“bed”、“陪”、“我”——却像是一道道滚烫的烙铁，精准无比地烫穿了他给自己筑起的那道名为“赎罪”的高墙。

~~他该拒绝的，她现在的身体根本承受不住任何拥挤，单人病床也容不下他这样的体型。~~ *可是面对她的索求，他根本无法说出一个“不”字。*

秦海一垂着眼，死死盯着自己摊开的掌心，喉结上下滑动着。病房里**昏暗的暮色**将他的轮廓切割得异常深邃，那双向来深不见底的眼眸里，此刻翻涌着几乎要将人溺毙的偏执与妥协。

“……好。”

他哑着嗓子吐出一个字，声线里带着一丝微颤。他慢慢站起身，脱掉脚上的皮鞋，甚至将那件沾染了三天尘埃与疲惫的外套脱了下来扔在沙发上，只穿着里面那件深色的衬衫。

单人病床很窄。秦海一没有像往常那样霸道地将她整个圈进怀里，而是小心翼翼地撑着**坚硬的金属床沿**，长腿跨了上去。他把自己一米八六的骨架尽可能地蜷缩、收拢，侧躺在病床最外侧那道**逼仄的边缘**上。

他的大半个后背甚至悬空在床外，全靠手肘和腰腹的力量稳住重心，绝不让自己的躯体压到她哪怕一寸。

秦海一侧着头，视线一瞬不瞬地凝视着近在咫尺的她。他缓缓伸出一只手，避开她腹部的吻合口和手背上的输液管，克制地隔着被子虚虚拢在她的腰侧，像是一道沉默而坚不可摧的防线。

“我上来了，就在这陪你。”他低下头，薄唇轻轻碰了碰她的额角，呼吸温热而平稳，“睡吧，秋煜。我守着你。”

