           document.getElementById('lustVal').textContent = charStats.lust;
           document.getElementById('semenBar').style.width = charStats.semen + '%';
           document.getElementById('semenVal').textContent = charStats.semen;
           document.getElementById('threshBar').style.width = charStats.threshold + '%';
           document.getElementById('threshVal').textContent = charStats.threshold;

